@st.cache_resource
def frontend_directory(assets):
    directory = TemporaryDirectory(prefix="reelmate-streamlit-ui-", ignore_cleanup_errors=True)
    for name, compressed in assets:
        (Path(directory.name) / name).write_bytes(gzip.decompress(base64.b64decode(compressed)))
    return directory


dist = ROOT / "frontend" / "dist"
if not all((dist / name).is_file() for name, _ in _UI_ASSETS):
    dist = Path(frontend_directory(_UI_ASSETS).name)

component = declare_component("studio", path=str(dist))
component(key=WIDGET, on_change=on_event, state={
    "project": public_project(st.session_state.active_project),
    "projects": service.projects(),
    "profiles": service.profiles(),
    "capabilities": service.capabilities(),
    "labels": LABELS,
    "rule_types": RULE_TYPES,
    "aspects": ASPECTS,
    "local": local_mode,
    "ack": st.session_state.get("ack"),
})
